from pathlib import Path

class FilmMarkup:
    def icon(self, name, extra=''):
        return f'<svg class="icon {extra}" aria-hidden="true"><use href="#i-{name}"/></svg>'

    def pet(self, extra=''):
        return f'<svg class="live-pet {extra}" viewBox="16 16 60 60" aria-hidden="true"><path class="pet-body"/><path class="pet-eyes"/></svg>'

    def avatar(self, role, extra=''):
        return f'<img class="{extra}" src="assets/brand/{role}.svg" alt="">'

    def sidebar(self):
        contacts=''.join(f'<div class="contact">{self.avatar(role)}<div><strong>{name}</strong><span>{label}</span></div></div>' for role,name,label in [('coordinator','Blot','Coordinator'),('researcher','Scout','Researcher'),('analyst','Dough','Analyst'),('writer','Penny','Writer')])
        return f'<aside class="sidebar"><div class="window-controls"><i></i><i></i><i></i>{self.icon("plus")}</div><div class="sidebar-search">{self.icon("search")}<span>Search your team</span></div><div class="sidebar-label mono">YOUR TEAM</div>{contacts}<div class="sidebar-label mono">GROUPS</div><div class="group-selected">{self.icon("grid")}<div><strong>Launch crew</strong><span>Blot, Scout, Dough, Penny</span></div></div><div class="sidebar-bottom">{self.icon("grid")}<span>Apps &amp; skills</span></div></aside>'

    def toolbar(self):
        return '<header class="app-toolbar"><span class="crew-mini">'+''.join(self.avatar(r) for r in ['researcher','analyst','writer'])+'</span><strong>Launch crew</strong><span class="toolbar-detail">4 teammates</span><span class="toolbar-dots">···</span></header>'

    def render(self):
        icons={'arrow':'<path d="M12 19V5M5 12l7-7 7 7"/>','plus':'<path d="M12 5v14M5 12h14"/>','file':'<path d="M14 3H5v18h14V8l-5-5ZM14 3v6h5M8 13h8M8 17h6"/>','check':'<path d="m5 12 4 4L19 6"/>','search':'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>','link':'<path d="m9 15 6-6M9 17l-1 1a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0M15 7l1-1a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0"/>','grid':'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>','external':'<path d="M6 18 18 6M6 6h12v12"/>'}
        parts=['<svg class="symbol-library" aria-hidden="true"><defs>'+''.join(f'<symbol id="i-{k}" viewBox="0 0 24 24">{v}</symbol>' for k,v in icons.items())+'</defs></svg>']
        parts += ['<main id="film" class="clip" data-start="0" data-duration="30" data-track-index="0"><div id="ground"></div>', f'<div id="brand" class="brand">{self.pet()}<span>Blot</span></div>', '<div id="chapter"><span id="chapter-task">01 / TASK</span><span id="chapter-team">02 / TEAM</span><span id="chapter-result">03 / RESULT</span></div>']
        parts += [f'<section id="intro" class="scene"><div class="intro-eyebrow mono">YOUR NEXT BIG IDEA STARTS HERE</div><div class="intro-title"><div class="mask"><span id="one">One</span></div><div class="mask"><span id="task">task<span id="period">.</span></span></div></div><div id="intro-caption">A whole team on it.</div><div id="peek-r" class="peek">{self.avatar("researcher")}</div><div id="peek-a" class="peek">{self.avatar("analyst")}</div><div id="peek-w" class="peek">{self.avatar("writer")}</div><div class="intro-rule"></div><span class="intro-bottom mono">AI TEAMMATES. SHARED CONTEXT. REAL WORK.</span></section>']
        parts += [f'<section id="app-scene" class="scene"><div id="app-window" class="app-window">{self.sidebar()}<div class="app-main">{self.toolbar()}<div class="welcome">{self.pet()}<h2>What are we working on?</h2><p>Give your team a task.</p></div><div class="app-bottom-note mono">FILES, CONTEXT AND YOUR TEAM. TOGETHER.</div></div></div></section>']
        parts += [f'<div id="request" class="request"><div id="request-text"><span id="request-part-1">Compare competitors</span><span id="request-part-2">and build a launch plan.</span><i id="caret"></i></div><div class="request-tools">{self.icon("plus")}<span>Message your team</span></div><div id="send-button">{self.icon("arrow")}</div><div id="sent-check">{self.icon("check")}</div></div><svg id="cursor" viewBox="0 0 40 48" aria-hidden="true"><path d="M3 2v35l10-10 8 17 7-3-8-16h15Z" fill="#27272a" stroke="#fff" stroke-width="3"/></svg>']
        parts += [f'<section id="team-scene" class="scene"><div class="team-title mask"><h2>Meet your team.</h2></div><div id="coordinator">{self.avatar("coordinator")}<div><strong>Blot</strong><span>Putting the right team on it.</span></div></div><svg id="team-routes" viewBox="0 0 1920 1080" aria-hidden="true"><path class="team-route route-r" d="M960 385C960 465 430 405 430 525"/><path class="team-route route-a" d="M960 385V525"/><path class="team-route route-w" d="M960 385C960 465 1490 405 1490 525"/></svg>']
        for key,role,label,desc,detail in [('r','researcher','Researcher','Find the facts.','Sources'),('a','analyst','Analyst','Connect the dots.','Insights'),('w','writer','Writer','Shape the plan.','Next steps')]:
            parts += [f'<article id="agent-{key}" class="agent-card {role}"><div class="role-index mono">{label.upper()}</div>{self.avatar(role)}<h3>{label}</h3><p>{desc}</p><div class="agent-status"><i></i><span>{detail}</span></div></article>']
        parts += ['<div class="team-bottom mono">ONE REQUEST. THE RIGHT SPECIALISTS.</div></section><section id="work-scene" class="scene"><div id="work-world" data-layout-allow-overflow>']
        parts += [f'<div id="research-bay" class="work-bay"><div class="work-heading"><div class="mono work-label blue">01 / RESEARCHER</div><h2><span>Find</span><span>the facts.</span></h2><p>Start with the sources.</p></div>{self.avatar("researcher","work-mascot")}']
        for j,title,copy in [(1,'Product pages','Audience. Features. Positioning.'),(2,'Feature lists','What each product can do.'),(3,'Public pricing','Plans and their limits.')]:
            parts += [f'<article class="source source-{j}"><div class="source-icon">{self.icon("link" if j==1 else "file")}</div><div><span class="mono blue">SOURCE / 0{j}</span><h3>{title}</h3><p>{copy}</p></div>{self.icon("check","source-check")}</article>']
        parts += [f'<div class="moving-source">{self.icon("file")}<span>Sources</span></div></div>']
        parts += [f'<div id="analysis-bay" class="work-bay"><div class="work-heading"><div class="mono work-label orange">02 / ANALYST</div><h2><span>Connect</span><span>the dots.</span></h2><p>Turn research into direction.</p></div>{self.avatar("analyst","work-mascot")}<article id="comparison"><header><span class="mono orange">COMPETITIVE OVERVIEW</span><h3>Compare what matters.</h3></header><div class="comparison-head"><span>Signal</span><span>What to compare</span></div>']
        for label,copy in [('Scope','Core capabilities'),('Workflow','From request to result'),('Collaboration','How teams share work')]:
            parts += [f'<div class="comparison-row"><strong>{label}</strong><span>{copy}</span><i></i></div>']
        parts += [f'<div class="insight-note">{self.icon("check")}<span>Key difference.</span></div></article></div>']
        parts += [f'<div id="writing-bay" class="work-bay"><div class="work-heading"><div class="mono work-label green">03 / WRITER</div><h2><span>Shape</span><span>the plan.</span></h2><p>Make the next move clear.</p></div>{self.avatar("writer","work-mascot")}<article id="draft"><div class="draft-file mono">{self.icon("file")}<span>launch-plan.md</span><span class="draft-tag">DRAFT</span></div><h3>Launch plan</h3>']
        for j,label,copy in [(1,'Positioning','Lead with team collaboration.'),(2,'Product demo','Show one complete task.'),(3,'Feedback loop','Test. Learn. Refine.')]:
            parts += [f'<div class="draft-row"><span>0{j}</span><strong>{label}</strong><p>{copy}</p></div>']
        parts += ['<div class="draft-caret"></div></article></div></div></section><div id="dark-iris" aria-hidden="true" data-layout-allow-overflow></div>']
        parts += ['<section id="handoff-scene" class="scene"><div class="handoff-eyebrow mono">SHARED CONTEXT / SHARED PROGRESS</div><div class="handoff-title mask"><h2><span>Built to build</span><span>on each other.</span></h2></div><svg id="handoff-routes" viewBox="0 0 1920 1080" aria-hidden="true"><path class="handoff-path" d="M475 685H840"/><path class="handoff-path" d="M1080 685H1445"/><path class="handoff-return" d="M1555 775C1555 965 960 995 960 820"/></svg>']
        for key,role in [('r','researcher'),('a','analyst'),('w','writer')]:
            parts += [f'<div id="node-{key}" class="handoff-node">{self.avatar(role)}<span>{role.title()}</span></div>']
        parts += [f'<div id="packet-sources" class="packet">{self.icon("file")}<span>Sources</span></div><div id="packet-insights" class="packet">{self.icon("file")}<span>Insights</span></div><div id="shared-context" class="mono">THE NEXT AGENT PICKS UP WHERE THE LAST LEFT OFF.</div></section><div id="paper-wipe" aria-hidden="true"></div>']
        parts += [f'<section id="report-scene" class="scene"><div class="report-heading"><span class="mono green">THE RESULT</span><div class="mask"><h2><span>From one</span><span>message to</span><span>a launch plan.</span></h2></div><p>Research. Comparison.<span>A clear next move.</span></p></div><div id="ready-message">{self.avatar("coordinator")}<div><strong>Blot</strong><p>Launch plan ready.</p></div>{self.icon("check")}</div></section>']
        parts += [f'<section id="result-scene" class="scene"><div id="result-window" class="app-window">{self.sidebar()}<div class="app-main">{self.toolbar()}<div class="result-conversation"><div class="mono green">TASK COMPLETE</div><h2><span>Ready in your</span><span>workspace.</span></h2><div class="result-reply">{self.avatar("coordinator")}<p>Launch plan ready.</p></div><div class="attachment">{self.icon("file")}<div><strong>Launch plan.md</strong><p>Research · comparison · next steps</p></div>{self.icon("external")}</div></div></div></div></section>']
        parts += [f'<article id="report-sheet"><div class="paper-toolbar mono">{self.icon("file")}<span>launch-plan.md</span><span class="paper-ready">READY</span></div><div class="paper-content"><span class="mono paper-eyebrow">COMPETITIVE OVERVIEW</span><h2>Launch plan<span>.</span></h2><div class="paper-rule"></div>']
        for j,label,copy in [(1,'Research','Product pages, features and public pricing.'),(2,'Positioning','Lead with team collaboration.'),(3,'Next steps','Build the demo. Gather feedback. Refine.')]:
            parts += [f'<div class="paper-section"><span class="paper-number">0{j}</span><div><h3>{label}</h3><p>{copy}</p></div></div>']
        parts += [f'<div class="paper-footer"><span>Sources included</span>{self.icon("check")}</div></div></article>']
        parts += ['<section id="final-scene" class="scene">']
        for key,role in [('r','researcher'),('a','analyst'),('w','writer')]:
            parts += [f'<div id="final-orbit-{key}" class="final-orbit">{self.avatar(role)}</div>']
        parts += [f'<div id="final-mark"><div class="pet-breath">{self.pet()}</div></div><div id="final-name">Blot</div><div id="final-line"><div class="mask"><span>One task.</span></div><div class="mask"><span>A whole team.</span></div></div><div id="final-cta"><span>Build your team</span>{self.icon("external")}</div><div id="final-footnote" class="mono">AI TEAMMATES THAT FINISH THE WORK.</div><div id="sonic-underlay" aria-hidden="true"></div></section><div id="edit-wipe" aria-hidden="true"></div></main>']
        automation='{&quot;version&quot;:1,&quot;lanes&quot;:[{&quot;target&quot;:&quot;volume&quot;,&quot;points&quot;:[{&quot;t&quot;:0,&quot;v&quot;:0},{&quot;t&quot;:0.28,&quot;v&quot;:0.64},{&quot;t&quot;:28.6,&quot;v&quot;:0.64},{&quot;t&quot;:30,&quot;v&quot;:0}]}]}'
        parts += [f'<audio id="music-bed" src="assets/music/happy-beats-business-moves-vol-10-by-ende-dot-app.mp3" data-start="0" data-duration="30" data-track-index="1" data-volume="0.64" data-automation="{automation}"></audio>']
        for j,(at,file,volume,duration) in enumerate([(0.27,'impactSoft_medium_001.ogg',.35,.18),(2.25,'card-slide-1.ogg',.2,.5),(3.05,'keypress-003.wav',.17,.2),(3.2,'keypress-003.wav',.15,.2),(3.4,'keypress-003.wav',.16,.2),(4.9,'click_003.ogg',.6,.05),(6.28,'impactSoft_medium_001.ogg',.16,.18),(6.82,'impactSoft_medium_001.ogg',.16,.18),(7.35,'impactSoft_medium_001.ogg',.16,.18),(9.2,'card-slide-1.ogg',.21,.5),(11.25,'card-slide-1.ogg',.18,.5),(13.15,'card-slide-1.ogg',.18,.5),(15.82,'click_003.ogg',.5,.05),(16.93,'click_003.ogg',.5,.05),(18.55,'impactBell_heavy_003.ogg',.13,.65),(25.55,'impactSoft_medium_001.ogg',.4,.18),(26.45,'impactBell_heavy_003.ogg',.13,.65)]):
            parts += [f'<audio id="sfx-{j}" src="assets/sfx/{file}" data-start="{at}" data-duration="{duration}" data-track-index="{2+j}" data-volume="{volume}"></audio>']
        css=Path('film.css').read_text(); js=Path('film.js').read_text()
        return '<!doctype html><html lang="en" data-resolution="landscape"><head><meta charset="utf-8"><meta name="viewport" content="width=1920,height=1080"><title>Blot — One task. A whole team.</title><script src="assets/vendor/gsap.min.js"></script><script src="assets/brand/pet-motion.js"></script><script src="assets/music/audio-data.js"></script><style>'+css+'</style></head><body><div id="root" data-composition-id="blot-launch" data-start="0" data-duration="30" data-width="1920" data-height="1080">'+''.join(parts)+'</div><script>'+js+'</script></body></html>'

if __name__=='__main__':
    Path('index.html').write_text(FilmMarkup().render())
